    [Theory]
    [MemberData(nameof(WordCases))]
    public void ExplicitCapsMatchesWordWithoutChangingSource(string name, string styles, string body,
        string numbering, string expected, bool wordCompatibility)
    {
        using var stream = new MemoryStream();
        using var doc = WordprocessingDocument.Create(stream, WordprocessingDocumentType.Document);
        var main = doc.AddMainDocumentPart();
        main.AddNewPart<StyleDefinitionsPart>().Styles = new Styles(styles);
        main.AddNewPart<NumberingDefinitionsPart>().Numbering = new Numbering(numbering);
        main.Document = new Document(new Body(body));
        _ = main.Document.Descendants().ToArray();
        _ = main.StyleDefinitionsPart!.Styles.Descendants().ToArray();
        _ = main.NumberingDefinitionsPart!.Numbering.Descendants().ToArray();
        var before = new[] { main.Document.OuterXml, main.StyleDefinitionsPart!.Styles.OuterXml,
            main.NumberingDefinitionsPart!.Numbering.OuterXml };
        foreach (var visitor in new DxpITextVisitor[] { new DxpHtmlVisitor(DxpHtmlVisitorConfig.CreatePlainConfig()),
            new DxpMarkdownVisitor(DxpMarkdownVisitorConfig.CreatePlainConfig()),
            new DxpPlainTextVisitor(DxpPlainTextVisitorConfig.CreateAcceptConfig()) })
        {
            var output = DxpExport.ExportToString(doc, visitor);
            var text = visitor is DxpPlainTextVisitor ? output : new HtmlParser().ParseDocument(output).Body!.TextContent;
            Assert.Contains("Item0", text); // Marker caps must not uppercase body text.
            for (var i = 0; i < 3; i++)
            {
                var line = Assert.Single(text.Split('\n').Where(line => line.Contains("Item" + i) || line.Contains("ITEM" + i)));
                Assert.StartsWith(expected, line.TrimStart());
            }
        }
        Assert.Equal(before, new[] { main.Document.OuterXml, main.StyleDefinitionsPart.Styles.OuterXml,
            main.NumberingDefinitionsPart.Numbering.OuterXml });
    }
}
